// Lightweight fallback for devices without WebGL. No remote resources.
export function mountSolar2D(node,{reduced=false,onSelect=()=>{}}={}){
 node.innerHTML='';const canvas=document.createElement('canvas');canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Interactive illustrated solar system. Use the planet buttons below for the same information.');node.append(canvas);const ctx=canvas.getContext('2d');if(!ctx)throw Error('Canvas unavailable');
 const names=['Mercury','Venus','Earth','Mars','Jupiter','Saturn','Uranus','Neptune'],colours=['#b5a492','#dca855','#548cff','#c46543','#bc946d','#dcc396','#7cbfc8','#526fe8'],sizes=[4,6,7,5,13,11,8,8],speeds=[.9,.7,.5,.4,.23,.17,.13,.1];let paused=reduced,selected=2,t=8,turn=0,w=0,h=0,frame,dead=false,last=performance.now(),positions=[];
 function resize(){w=node.clientWidth;h=innerWidth<=650?365:470;const d=Math.min(devicePixelRatio,1.5);canvas.width=w*d;canvas.height=h*d;canvas.style.width=w+'px';canvas.style.height=h+'px';ctx.setTransform(d,0,0,d,0,0)}const observer=new ResizeObserver(resize);observer.observe(node);resize();
 function draw(now){if(dead)return;frame=requestAnimationFrame(draw);if(!paused&&!document.hidden)t+=Math.min((now-last)/1000,.05)*.2;last=now;ctx.clearRect(0,0,w,h);const cx=w*.5,cy=h*.48,R=Math.min(w*.42,h*.65);ctx.fillStyle='#c4d1ff';for(let i=0;i<80;i++){const x=((i*137.508)%w),y=((i*71.34)%h);ctx.globalAlpha=.2+(i%4)*.15;ctx.beginPath();ctx.arc(x,y,i%5===0?1.2:.7,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.strokeStyle='#68729d50';ctx.lineWidth=1;for(let i=0;i<8;i++){const r=R*(.19+i*.115);ctx.beginPath();ctx.ellipse(cx,cy,r,r*.52,0,0,Math.PI*2);ctx.stroke()}const glow=ctx.createRadialGradient(cx,cy,3,cx,cy,57);glow.addColorStop(0,'#ffdf89');glow.addColorStop(.3,'#ffbd49');glow.addColorStop(.4,'#ffbd4950');glow.addColorStop(1,'#ffbd4900');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(cx,cy,57,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff1b7';ctx.font='600 11px Jakarta, sans-serif';ctx.textAlign='center';ctx.fillText('Sun',cx,cy+37);positions=[];for(let i=0;i<8;i++){const r=R*(.19+i*.115),a=t*speeds[i]+i*1.65+turn,x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r*.52,s=sizes[i]*(w<500?.8:1);positions.push({x,y,s});if(i===selected){ctx.strokeStyle='#b7ff45';ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(x,y,s+6,s*.75+5,0,0,Math.PI*2);ctx.stroke()}if(i===5){ctx.strokeStyle='#cab492';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(x,y,s*1.9,s*.6,-.4,0,Math.PI*2);ctx.stroke()}const p=ctx.createRadialGradient(x-s*.4,y-s*.4,0,x,y,s);p.addColorStop(0,colours[i]);p.addColorStop(.7,colours[i]);p.addColorStop(1,'#1b2444');ctx.fillStyle=p;ctx.beginPath();ctx.arc(x,y,s,0,Math.PI*2);ctx.fill();if(i===2){ctx.fillStyle='#67b889';ctx.beginPath();ctx.ellipse(x-1,y-2,s*.35,s*.65,.4,0,Math.PI*2);ctx.fill()}ctx.fillStyle=i===selected?'#d1ff8a':'#c8d0ed';ctx.font=(i===selected?'700 ':'500 ')+(w<500?'9':'11')+'px Jakarta, sans-serif';ctx.fillText(names[i],Math.max(25,Math.min(w-25,x)),y+s+16)}ctx.textAlign='left';ctx.fillStyle='#919dbd';ctx.font='10px Jakarta, sans-serif';ctx.fillText('Lightweight illustrated view',19,h-20)}
 const click=e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;let nearest=-1,dist=30;positions.forEach((p,i)=>{const d=Math.hypot(x-p.x,y-p.y);if(d<dist){nearest=i;dist=d}});if(nearest!==-1){selected=nearest;onSelect(selected)}};const select=e=>{selected=e.detail},toggle=()=>{paused=!paused},reset=()=>{t=8;turn=0;selected=2;onSelect(2)};canvas.addEventListener('click',click);window.addEventListener('zuno-planet',select);window.addEventListener('zuno-orbit-toggle',toggle);window.addEventListener('zuno-orbit-reset',reset);draw(performance.now());return()=>{dead=true;cancelAnimationFrame(frame);observer.disconnect();canvas.removeEventListener('click',click);window.removeEventListener('zuno-planet',select);window.removeEventListener('zuno-orbit-toggle',toggle);window.removeEventListener('zuno-orbit-reset',reset)};
}
